from backend_client import fetch_tools

def startup_agent(data):
    backend_ready = bool(data.get("backend_ready", False))
    tools = data.get("tools", [])
    registered = []
    if backend_ready:
        registered = fetch_tools(tools)
    return {
        "startup_completed": True,
        "registered_tools": registered,
        "registered_count": len(registered),
        "backend_ready_at_startup": backend_ready,
    }
